import sys
import heapq

def main():
    import sys
    import heapq

    def read_ints():
        return map(int, sys.stdin.readline().split())

    n, k = read_ints()
    times = list(read_ints())
    edges = [tuple(read_ints()) for _ in range(n - 1)]

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u - 1].append(v - 1)
        adj[v - 1].append(u - 1)

    # Function to perform DFS and get the minimum time in the first k nodes
    def dfs(root):
        stack = [(root, -1)]  # (node, parent)
        visited = [False] * n
        min_times = []

        while stack:
            node, parent = stack.pop()
            if visited[node]:
                continue
            visited[node] = True
            heapq.heappush(min_times, times[node])
            if len(min_times) > k:
                heapq.heappop(min_times)

            for neighbor in adj[node]:
                if neighbor != parent:
                    stack.append((neighbor, node))

        return min_times[0]

    # Try all possible roots
    max_grade = 0
    for root in range(n):
        grade = dfs(root)
        max_grade = max(max_grade, grade)

    print(max_grade)

if __name__ == "__main__":
    main()
